            // explicit check
            assertEquals(7654321l, bwOpts.getMaxLatency(TimeUnit.MILLISECONDS));
            assertEquals(9898989l, bwOpts.getTimeout(TimeUnit.MILLISECONDS));
            assertEquals(42, bwOpts.getMaxWriteThreads());
