public void retriesAreCompleted() {
    for (int i = 0; i < maxRetries; i++) {
        Assert.assertEquals(i, retry.retriesCompleted());
        // canRetry doesn't alter retry's state
        retry.canRetry();
        Assert.assertEquals(i, retry.retriesCompleted());
