    assertFail(tabletMeta, ke, new TServerInstance("127.0.0.2:9997", 5));
    assertFail(tabletMeta, new KeyExtent(new Text("1"), null, new Text("m")), tsi);
    assertFail(tabletMeta, new KeyExtent(new Text("1"), new Text("r"), new Text("m")), tsi);
