        scanner.clearColumns();
        scanner.setBatchSize(3);
        scanner.fetchColumnFamily(new Text(String.format("%03d", 1)));
        Iterator<Entry<Key, Value>> iter = scanner.iterator();
        if (iter.hasNext()) {
            Entry<Key, Value> entry = iter.next();
