public void testTableDelete() throws Exception {
    boolean mutationsRejected = false;
    try {
        final String[] names = getUniqueNames(2);
        final String table1 = names[0], table2 = names[1];
        TableOperations tops = connector.tableOperations();
        tops.create(table1);
