        m1.put("col1", "", "val1");
        m1.put("col2", "", "val2");
        bw1.addMutation(m1);
        bw2.addMutation(m1);
        tops.delete(table1);
        tops.delete(table2);
        Mutation m2 = new Mutation("bar");
        m2.put("col1", "", "val1");
        m2.put("col2", "", "val2");
        try {
            bw1.addMutation(m2);
            bw2.addMutation(m2);
        } catch (MutationsRejectedException e) {
            // Pass - Mutations might flush immediately
            mutationsRejected = true;
        }
