                // Mutations might have flushed before the table offline occurred
                mtbw.close();
            } catch (MutationsRejectedException e) {
                // Pass
                mutationsRejected = true;
            }
        }
    }
    Assert.assertTrue("Expected mutations to be rejected.", mutationsRejected);
}

